11	import { Close } from "pixelarticons/react/Close";
12	import PillButton from "@/components/case-study/PillButton.astro";
13	---
14	
15	<div
16	  id="lightbox"
17	  class="lightbox-backdrop fixed inset-0 z-50 items-center justify-center p-6 sm:p-20"
18	  role="dialog"
19	  aria-modal="true"
20	  aria-label="Enlarged media"
21	  aria-hidden="true"
22	>
23	  <div id="lightbox-content" class="lightbox-content relative">
24	    <PillButton
25	      id="lightbox-close"
26	      icon={Close}
27	      label="Close"
28	      size="sm"
29	      iconColor="oklch(58.6% 0.253 17.585)"
30	      background="color-mix(in oklch, oklch(58.6% 0.253 17.585) 15%, transparent)"
31	      class="absolute right-0 bottom-full mb-4"
32	    />
33	    <div id="lightbox-media" class="overflow-hidden rounded-lg"></div>
34	  </div>
35	</div>
36	
37	<style>
38	  /* --lightbox-backdrop (global.css) is its own theme-aware token, not
39	     --portfolio-ink — a near-black scrim reads fine over a dark page, but
40	     the same near-black tint over the light theme's page just looked like
41	     a broken dark overlay, not an intentional scrim. */
42	  /* Visibility is driven entirely by .is-open now, not Tailwind's `hidden`
43	     utility — Astro scopes this <style> block, which raises this
44	     selector's specificity above a plain global `.hidden { display:none }`
45	     utility class, so `display:flex` declared here would otherwise beat
46	     `hidden` and leave the (invisible but interactive) backdrop covering
47	     the page even when "closed". pointer-events:none on the closed state
48	     is what actually keeps it out of the way; opacity/display are purely
49	     visual. */
50	  .lightbox-backdrop {
51	    background-color: var(--lightbox-backdrop);
52	    display: flex;
53	    opacity: 0;
54	    pointer-events: none;
55	    backdrop-filter: blur(0);
56	    -webkit-backdrop-filter: blur(0);
57	    transition:
58	      opacity 500ms cubic-bezier(0.22, 1, 0.36, 1),
59	      backdrop-filter 500ms cubic-bezier(0.22, 1, 0.36, 1),
60	      -webkit-backdrop-filter 500ms cubic-bezier(0.22, 1, 0.36, 1);
61	  }
62	
63	  .lightbox-backdrop.is-open {
64	    opacity: 1;
65	    pointer-events: auto;
66	    backdrop-filter: blur(calc(16px / 2));
67	    -webkit-backdrop-filter: blur(calc(16px / 2));
68	  }
69	
70	  .lightbox-content {
71	    opacity: 0;
72	    transform: scale(0.96);
73	    transition:
74	      opacity 500ms cubic-bezier(0.22, 1, 0.36, 1),
75	      transform 500ms cubic-bezier(0.22, 1, 0.36, 1);
76	  }
77	
78	  .lightbox-backdrop.is-open .lightbox-content {
79	    opacity: 1;
80	    transform: scale(1);
81	  }
82	
83	  #lightbox-media :global(img),
84	  #lightbox-media :global(iframe) {
85	    display: block;
86	  }
87	
88	  @media (prefers-reduced-motion: reduce) {
89	    .lightbox-backdrop,
90	    .lightbox-content {
91	      transition-duration: 0.01ms;
92	    }
93	  }
94	</style>
95	
96	<script>
97	  import { MEDIA_FRAME_SHADOW } from "@/lib/media";
98	
99	  // Delegated listener so any current or future [data-lightbox-trigger]
100	  // element (an <img>-wrapping LightboxImage, or the Loom overview button)
101	  // opens this one shared instance — the script never needs to know how
102	  // many triggers exist or where they live in the DOM.
103	  const backdrop = document.getElementById("lightbox");
104	  const content = document.getElementById("lightbox-content");
105	  const media = document.getElementById("lightbox-media");
106	  const closeButton = document.getElementById("lightbox-close");
107	
108	  let lastFocusedTrigger: HTMLElement | null = null;
109	
110	  function prefersReducedMotion() {
111	    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
112	  }
113	
114	  // Shared sizing rule for both images and the Loom iframe: scale the
115	  // source's natural size by 1.3x, but on narrow viewports skip the
116	  // multiplier entirely and just fit the media to the screen instead of
117	  // scaling-then-clipping. Above that breakpoint, the 1.3x result is still
118	  // re-clamped against 90% of the viewport as a ceiling for unusually
119	  // large source images.
120	  function computeEnlargedSize(naturalWidth: number, naturalHeight: number) {
121	    const ratio = naturalWidth / naturalHeight;
122	    const isNarrowViewport = window.innerWidth < 640;
123	
124	    let width: number;
125	    if (isNarrowViewport) {
126	      width = window.innerWidth * 0.92;
127	    } else {
128	      width = Math.min(naturalWidth * 1.3, window.innerWidth * 0.9);
129	    }
130	
131	    let height = width / ratio;
132	    const maxHeight = window.innerHeight * (isNarrowViewport ? 0.85 : 0.9);
133	    if (height > maxHeight) {
134	      height = maxHeight;
135	      width = height * ratio;
136	    }
137	
138	    return { width, height };
139	  }
140	
141	  // MEDIA_FRAME_SHADOW's inset layers are a bevel meant to sit on the
142	  // clipping container's own edge, not on the media inside it — putting the
143	  // shadow directly on the <img>/<iframe> let the inset highlight render as
144	  // a visible sliver inside the media's own content instead of flush
145	  // against the rounded corner (same bug, same fix, as LightboxImage.astro).
146	  // So #lightbox-media itself is sized and shadowed here; the leaf element
147	  // just fills it edge to edge.
148	  function buildImageMedia(trigger: HTMLElement) {
149	    const sourceImg = trigger.querySelector("img");
150	    if (!sourceImg) return null;
151	
152	    const { width, height } = computeEnlargedSize(
153	      sourceImg.naturalWidth || sourceImg.width,
154	      sourceImg.naturalHeight || sourceImg.height,
155	    );
156	
157	    const img = document.createElement("img");
158	    img.src = sourceImg.src;
159	    img.alt = sourceImg.alt;
160	    img.className = "block size-full object-cover";
161	    return { el: img, width, height };
162	  }
163	
164	  function buildIframeMedia(trigger: HTMLElement) {
165	    const src = trigger.getAttribute("data-lightbox-src");
166	    if (!src) return null;
167	
168	    // No natural size to read for an iframe — use its fixed aspect ratio
169	    // (matches the inline embed box this replaces) as the basis instead.
170	    const { width, height } = computeEnlargedSize(1008, 567);
171	
172	    const iframe = document.createElement("iframe");
173	    iframe.src = src;
174	    iframe.title = "Video walkthrough";
175	    iframe.allow = "fullscreen; picture-in-picture";
176	    iframe.allowFullscreen = true;
177	    iframe.className = "block size-full";
178	    iframe.style.border = "0";
179	    return { el: iframe, width, height };
180	  }
181	
182	  function openLightbox(trigger: HTMLElement) {
183	    if (!backdrop || !media) return;
184	
185	    const type = trigger.getAttribute("data-lightbox-type");
186	    const built =
187	      type === "iframe" ? buildIframeMedia(trigger) : buildImageMedia(trigger);
188	    if (!built) return;
189	
190	    media.replaceChildren(built.el);
191	    media.style.width = `${built.width}px`;
192	    media.style.height = `${built.height}px`;
193	    media.style.boxShadow = MEDIA_FRAME_SHADOW;
194	    lastFocusedTrigger = trigger;
195	
196	    backdrop.setAttribute("aria-hidden", "false");
197	    // Force layout before adding .is-open so the opacity/transform
198	    // transition actually runs instead of snapping straight to the open
199	    // state (toggling aria-hidden and adding the transition class in the
200	    // same tick would otherwise skip the transition on the first paint).
201	    requestAnimationFrame(() => backdrop.classList.add("is-open"));
202	
203	    document.body.style.overflow = "hidden";
204	    closeButton?.focus();
205	  }
206	
207	  function closeLightbox() {
208	    if (!backdrop || !media) return;
209	
210	    backdrop.classList.remove("is-open");
211	    const finish = () => {
212	      backdrop.setAttribute("aria-hidden", "true");
213	      media.replaceChildren();
214	      document.body.style.overflow = "";
215	      lastFocusedTrigger?.focus();
216	      lastFocusedTrigger = null;
217	    };
218	
219	    if (prefersReducedMotion()) {
220	      finish();
221	    } else {
222	      backdrop.addEventListener("transitionend", finish, { once: true });
223	    }
224	  }
225	
226	  document.addEventListener("click", (e) => {
227	    const trigger = (e.target as HTMLElement)?.closest<HTMLElement>(
228	      "[data-lightbox-trigger]",
229	    );
230	    if (trigger) {
231	      e.preventDefault();
232	      openLightbox(trigger);
233	    }
234	  });
235	
236	  // LightboxImage's trigger is a <span role="button">, which — unlike a
237	  // native <button> — doesn't activate on Enter/Space by itself, so this
238	  // listener does it manually. PillButton's trigger IS a real <button>,
239	  // which the browser already activates on Enter/Space by dispatching its
240	  // own synthesized click — e.preventDefault() here doesn't suppress that,
241	  // so without the tagName check below, pressing Enter/Space on a button
242	  // trigger called openLightbox() twice (once here, once from the
243	  // resulting native click). Excluding <button> elements isn't dead code —
244	  // it's what stops that double-fire.
245	  document.addEventListener("keydown", (e) => {
246	    if (e.key !== "Enter" && e.key !== " ") return;
247	    const trigger = (e.target as HTMLElement)?.closest<HTMLElement>(
248	      "[data-lightbox-trigger]",
249	    );
250	    if (trigger && trigger.tagName !== "BUTTON") {
251	      e.preventDefault();
252	      openLightbox(trigger);
253	    }
254	  });
255	
256	  closeButton?.addEventListener("click", closeLightbox);
257	
258	  backdrop?.addEventListener("click", (e) => {
259	    if (e.target === backdrop) closeLightbox();
260	  });
261	
262	  document.addEventListener("keydown", (e) => {
263	    if (e.key !== "Escape") return;
264	    if (!backdrop?.classList.contains("is-open")) return;
265	    closeLightbox();
266	  });
267	
268	  // Minimal focus trap: if focus ever lands outside the lightbox while
269	  // it's open, pull it back to the close button.
270	  document.addEventListener("focusin", (e) => {
271	    if (!backdrop?.classList.contains("is-open")) return;
272	    if (content?.contains(e.target as Node)) return;
273	    closeButton?.focus();
274	  });
275	</script>
